def _silence_stdout():
    """Point fd 1 at devnull so the flush at interpreter exit cannot fail again."""
    try:
        fd = os.open(os.devnull, os.O_WRONLY)
        try:
            os.dup2(fd, sys.stdout.fileno())
        finally:
            os.close(fd)
    except (OSError, ValueError, AttributeError):
        pass  # stdout has no real descriptor (e.g. replaced in-process)


def _emit(text):
    """Write the result to stdout; returns the exit status.

    A reader that closes early (``| head -1``) is not an error: quiet exit 0.
    Any other failure to write is one line on stderr and exit 2.
    """
    if sys.stdout is None:
        print("%s: cannot write output: standard output is closed" % PROG, file=sys.stderr)
        return 2
    try:
        raw = getattr(sys.stdout, "buffer", None)
        if raw is not None:
            sys.stdout.flush()
            raw.write(text.encode("utf-8"))  # UTF-8 whatever the locale says
            raw.flush()
        else:
            sys.stdout.write(text)  # text-only stand-in (e.g. StringIO)
            sys.stdout.flush()
    except BrokenPipeError:
        _silence_stdout()
